begin;
create temporary table p8_checks(name text primary key);
grant all on p8_checks to anon,authenticated;
create temporary table p8_baseline as select (select count(*) from public.orders) orders,(select count(*) from public.notifications) notifications;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
('88000000-0000-4000-8000-000000000001','p8-a@example.invalid',now(),'{}'),('88000000-0000-4000-8000-000000000002','p8-b@example.invalid',now(),'{}');
insert into auth.sessions(id,user_id,created_at,not_after) values
('88100000-0000-4000-8000-000000000001','88000000-0000-4000-8000-000000000001',now(),now()+interval '1 hour'),('88100000-0000-4000-8000-000000000002','88000000-0000-4000-8000-000000000002',now(),now()+interval '1 hour');
insert into public.products(id,product_type,status,name,slug,published_at) values('88200000-0000-4000-8000-000000000001','lamp','active','Rollback checkout fixture','p8-rollback-lamp',now());
insert into public.product_variants(id,product_id,sku,title,price_pkr,track_inventory) values('88300000-0000-4000-8000-000000000001','88200000-0000-4000-8000-000000000001','P8-ROLLBACK','Fixture',1000,true);
insert into public.inventory_balances(variant_id,location_id,on_hand) select '88300000-0000-4000-8000-000000000001',id,5 from public.inventory_locations where code='MAIN-PK';
update public.shipping_zones set is_active=false;
insert into public.shipping_zones(id,code,name,country_code,cities,provinces,is_nationwide,is_active) values('88400000-0000-4000-8000-000000000001','P8-ROLLBACK','Rollback Lahore','PK',array['Lahore'],array['Punjab'],false,true);
insert into public.shipping_rules(id,zone_id,name,flat_fee_pkr,free_shipping_threshold_pkr,cod_max_order_pkr,estimated_days_min,estimated_days_max) values('88500000-0000-4000-8000-000000000001','88400000-0000-4000-8000-000000000001','Rollback delivery',250,1900,10000,3,5);
insert into public.discounts(code,name,discount_type,percentage_bps) values('P8-ROLLBACK','Rollback discount','percentage',1000);
set local role anon;
select set_config('request.jwt.claims','{}',true);
select public.commerce_cart_add(repeat('8',64),'88300000-0000-4000-8000-000000000001',2);
do $$ declare q jsonb; b jsonb; begin
 q:=public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');
 if (q->'cart'->'quote'->>'subtotal_pkr')::int<>2000 or (q->'cart'->'quote'->>'shipping_pkr')::int<>0 or (q->'cart'->'quote'->>'total_pkr')::int<>2000 then raise exception 'quote totals failed'; end if;
 b:=public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');
 if q->>'revision'<>b->>'revision' then raise exception 'stable revision changed'; end if;
 insert into p8_checks values('canonical guest quote, free threshold and stable revision');
 begin perform public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Karachi","province":"Sindh"}');raise exception 'unsupported area accepted';exception when others then if sqlerrm<>'delivery_area_unsupported' then raise;end if;end;
 begin perform public.checkout_quote(repeat('8',64),'{"country":"US","city":"Lahore","province":"Punjab"}');raise exception 'foreign country accepted';exception when others then if sqlerrm<>'invalid_delivery_address' then raise;end if;end;
 begin perform public.checkout_quote(repeat('9',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');raise exception 'empty cart accepted';exception when others then if sqlerrm<>'empty_cart' then raise;end if;end;
 insert into p8_checks values('unsupported geography, foreign country and empty cart denial');
 perform public.commerce_cart_apply_discount(repeat('8',64),'P8-ROLLBACK');
 q:=public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');
 if (q->'cart'->'quote'->>'discount_pkr')::int<>200 or (q->'cart'->'quote'->>'shipping_pkr')::int<>250 or (q->'cart'->'quote'->>'total_pkr')::int<>2050 then raise exception 'discount shipping threshold failed';end if;
 if q->>'revision'=b->>'revision' then raise exception 'discount did not change revision';end if;
 insert into p8_checks values('discounted subtotal controls threshold and changes revision');
end $$;
reset role;
update public.shipping_rules set cod_max_order_pkr=1000 where id='88500000-0000-4000-8000-000000000001';
set local role anon;
do $$ begin begin perform public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');raise exception 'COD limit accepted';exception when others then if sqlerrm<>'cod_not_eligible' then raise;end if;end;insert into p8_checks values('COD upper limit enforced');end $$;
reset role;
update public.shipping_rules set cod_max_order_pkr=10000,remote_surcharge_pkr=100 where id='88500000-0000-4000-8000-000000000001';
set local role anon;
do $$ declare q jsonb;begin q:=public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');if (q->'cart'->'quote'->>'total_pkr')::int<>2150 then raise exception 'surcharge not included';end if;insert into p8_checks values('configured surcharge included');end $$;
reset role;
update public.discounts set is_active=false where code='P8-ROLLBACK';
set local role anon;
do $$ begin begin perform public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');raise exception 'expired discount accepted';exception when others then if sqlerrm<>'discount_not_eligible' then raise;end if;end;insert into p8_checks values('inactive discount requires review');end $$;
reset role;
update public.discounts set is_active=true where code='P8-ROLLBACK';
update public.inventory_reservations set expires_at=now()-interval '1 minute' where variant_id='88300000-0000-4000-8000-000000000001';
select app_private.release_expired_inventory_reservations();
update public.inventory_balances set on_hand=0 where variant_id='88300000-0000-4000-8000-000000000001';
set local role anon;
do $$ begin begin perform public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');raise exception 'unavailable stock accepted';exception when others then if sqlerrm<>'insufficient_stock' then raise;end if;end;insert into p8_checks values('expired reservation and unavailable stock rejected');end $$;
reset role;
update public.inventory_balances set on_hand=5 where variant_id='88300000-0000-4000-8000-000000000001';
set local role anon;
do $$ declare q jsonb;begin q:=public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');if not (q->>'needs_stock_revalidation')::boolean then raise exception 'expired reservation not disclosed';end if;insert into p8_checks values('available but expired stock reservation disclosed');end $$;
select public.commerce_cart_set_quantity(repeat('8',64),'88300000-0000-4000-8000-000000000001',2);
reset role;
update public.product_variants set price_pkr=1100 where id='88300000-0000-4000-8000-000000000001';
set local role anon;
do $$ declare q jsonb;begin q:=public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');if (q->'cart'->'quote'->>'subtotal_pkr')::int<>2200 then raise exception 'stale price accepted';end if;insert into p8_checks values('current product price replaces stale client totals');end $$;
reset role;
update public.shipping_rules set is_active=false where id='88500000-0000-4000-8000-000000000001';
set local role anon;
do $$ begin begin perform public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');raise exception 'missing rule accepted';exception when others then if sqlerrm<>'delivery_area_unsupported' then raise;end if;end;insert into p8_checks values('no active delivery rule fails closed');end $$;
reset role;
update public.shipping_rules set is_active=true where id='88500000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"88000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"88100000-0000-4000-8000-000000000001"}',true);
select public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');
select set_config('request.jwt.claims','{"sub":"88000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"88100000-0000-4000-8000-000000000002"}',true);
do $$ begin begin perform public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');raise exception 'foreign cart exposed';exception when others then if sqlerrm<>'empty_cart' then raise;end if;end;insert into p8_checks values('account cart isolation after guest claim');end $$;
reset role;
update auth.sessions set not_after=now()-interval '1 minute' where id='88100000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"88000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"88100000-0000-4000-8000-000000000001"}',true);
do $$ begin begin perform public.checkout_quote(repeat('8',64),'{"country":"PK","city":"Lahore","province":"Punjab"}');raise exception 'expired session accepted';exception when others then if sqlerrm<>'authentication_required' then raise;end if;end;insert into p8_checks values('expired account session denied');end $$;
reset role;
do $$ begin
 if (select reserved from public.inventory_balances where variant_id='88300000-0000-4000-8000-000000000001')<>2 then raise exception 'quote double reserved stock';end if;
 if (select count(*) from public.orders)<>(select orders from p8_baseline) or (select count(*) from public.notifications)<>(select notifications from p8_baseline) then raise exception 'quote created business events';end if;
 insert into p8_checks values('quotes do not reserve twice, create orders or notifications');
end $$;
select name from p8_checks order by name;
rollback;
